const CIA_IRQ_PROGRAM_BASE64 =
    '';

export const CIA_IRQ_PROGRAM_SHA256 =
    '13437a077249ec57a4f03ff69478cc359f1494634722053abe27aa6123f2679b';

export function createCiaIrqProgram(latch) {
    const code = Uint8Array.from(Buffer.from(CIA_IRQ_PROGRAM_BASE64, 'base64'));
    const signature = [0xA9, 0x02, 0x8D, 0x04, 0xDC];
    let offset = -1;
    for (let i = 0; i <= code.length - signature.length; i++) {
        let matches = true;
        for (let j = 0; j < signature.length; j++) {
            if (code[i + j] !== signature[j]) matches = false;
        }
        if (matches) {
            offset = i + 1;
            break;
        }
    }
    if (offset < 0) throw new Error('CIA latch immediate not found');
    code[offset] = latch;
    return code;
}
